/**
 * Content and measured geometry for each part of the vehicle.
 *
 * Geometry (bounding boxes, triangle counts, part heights) is generated by
 * `npm run model:prepare` and imported from geometry.json, so the copy can never
 * claim a dimension the actual mesh does not have. The written specifications
 * come from NASA flight manual stage data and the Apollo Operations Plan.
 */
import geometry from './generated/geometry.json'

export type PartId = 'les' | 'cm' | 'sm' | 'sla' | 'iu' | 'sivb' | 'sii' | 'sic'

export interface PartSpec {
  label: string
  value: string
}

export interface Part {
  id: PartId
  /** Vehicle designation, e.g. "S-IC". */
  code: string
  /** Full name shown in the panel heading. */
  name: string
  /** Position in the vehicle, base to tip. */
  order: number
  blurb: string
  specs: PartSpec[]
}

