export const PART_BY_ID = Object.fromEntries(PARTS.map((p) => [p.id, p])) as Record<PartId, Part>

/**
 * Scroll order runs top-down, from the escape tower to the engines, because the
 * camera enters looking straight down at the vehicle.
 */
export const SCROLL_PART_ORDER: PartId[] = [...PARTS].sort((a, b) => b.order - a.order).map((p) => p.id)

interface GeometryPart {
  id: PartId
  label: string
  from: number
  to: number
  tris: number
  meshes: number
  bbox: {
    min: [number, number, number]
    max: [number, number, number]
    size: [number, number, number]
    center: [number, number, number]
  }
}

const GEOMETRY = geometry as unknown as { heightM: number; parts: GeometryPart[] }

export const PART_GEOMETRY: Record<PartId, GeometryPart['bbox']> = Object.fromEntries(
  GEOMETRY.parts.map((p) => [p.id, p.bbox]),
) as Record<PartId, GeometryPart['bbox']>

/**
 * The prep script puts the base at y=0 and the tip at y=110.6. The scene
 * translates the whole vehicle by this amount so the stack is centred on the
 * origin, which keeps camera orbits and the exploded view symmetric.
 */
export const VEHICLE_Y_OFFSET = -VEHICLE_HEIGHT_M / 2

/** Part centres in scene space, with the centring offset already applied. */
export const PART_CENTER: Record<PartId, [number, number, number]> = Object.fromEntries(
  GEOMETRY.parts.map((p) => [
    p.id,
    [p.bbox.center[0], p.bbox.center[1] + VEHICLE_Y_OFFSET, p.bbox.center[2]] as [number, number, number],
  ]),
) as Record<PartId, [number, number, number]>

/** Measured, not nominal: the actual width of each part in the shipped mesh. */
export const PART_TRIANGLES: Record<PartId, number> = Object.fromEntries(
  GEOMETRY.parts.map((p) => [p.id, p.tris]),
) as Record<PartId, number>

